const aliases={baboy:'pork',manok:'chicken',isda:'fish',hipon:'shrimp',itlog:'egg',kanin:'rice',bigas:'rice',toyo:'soy',suka:'vinegar',patis:'fish sauce',bawang:'garlic',sibuyas:'onion',kamatis:'tomato',luya:'ginger',mantika:'oil',asin:'salt',paminta:'pepper',gata:'coconut milk',sitaw:'green beans',talong:'eggplant',monggo:'mung',tokwa:'tofu','ground beef':'beef','green onions':'onion','minced garlic':'garlic','sesame oil':'oil','soy sauce':'soy'};
function cleanLine(line){return line.replace(/[\u{1F300}-\u{1FAFF}\u2600-\u27BF]/gu,'').replace(/^[-*•]\s*/,'').replace(/\s+/g,' ').trim();}
export function cleanRecipeText(text){return text.split(/\r?\n/).map(cleanLine).filter(line=>line&&!noise.some(rule=>rule.test(line))).join('\n');}
function number(raw=''){const value=raw.trim();if(fractions[value]!==undefined)return fractions[value];const mixed=value.match(/^(\d+)\s+([½¼¾⅓⅔])$/);if(mixed)return Number(mixed[1])+fractions[mixed[2]];const slash=value.match(/^(\d+)\s*\/\s*(\d+)$/);if(slash)return Number(slash[1])/Number(slash[2]);return Number(value)||0;}
function grams(quantity,unit,item){const u=unit.toLowerCase(),name=item.toLowerCase();if(['g','gram','grams'].includes(u))return quantity;if(['kg','kilo'].includes(u))return quantity*1000;if(['ml'].includes(u))return /sesame oil/.test(name)?quantity*.92:/soy sauce|toyo/.test(name)?quantity*1.1:quantity;if(u==='l')return quantity*1000;if(['oz','ounce','ounces'].includes(u))return quantity*28.3495;if(['lb','pound','pounds'].includes(u))return quantity*453.592;if(['tbsp','tablespoon','tablespoons','kutsara'].includes(u))return quantity*(/oil|mantika/.test(name)?14:15);if(['tsp','teaspoon','teaspoons','kutsarita'].includes(u))return quantity*5;if(['clove','cloves'].includes(u))return quantity*3;if(['piece','pieces','piraso'].includes(u)&&/egg|itlog/.test(name))return quantity*50;if(['cup','cups','tasa'].includes(u)&&/rice|bigas|kanin/.test(name))return quantity*185;if(['cup','cups','tasa'].includes(u)&&/oat/.test(name))return quantity*80;return null;}
