function strength(line){return line.replace(/[*_#]/g,'').trim();}
export function matchIngredient(name,ingredientMap){const raw=name.toLowerCase().replace(/[^a-z\s]/g,' ').replace(/\b(extra lean|large|small|raw weight|raw|boneless|fillet|fillets|minced|fresh|of choice)\b/g,'').replace(/\s+/g,' ').trim(),translated=Object.entries(aliases).find(([word])=>raw.includes(word))?.[1]||raw,entries=Object.entries(ingredientMap),direct=entries.find(([id,item])=>translated.includes(id)||item.name.toLowerCase().includes(translated)||translated.includes(item.name.toLowerCase().split(',')[0]));if(direct)return direct[0];let best='',score=0;for(const [id,item]of entries){const words=new Set((id+' '+item.name).toLowerCase().split(/[^a-z]+/).filter(x=>x.length>2)),hits=translated.split(' ').filter(word=>words.has(word)).length;if(hits>score){score=hits;best=id;}}return score?best:'';}
