const ocrWords=new Set('tbsp tsp kcal protein carbs serving servings gochujang gochugaru sriracha kangkong palengke ingredients method recipe chicken beef pork rice garlic onion pepper salt sauce oil cup cups gram grams minutes'.split(' '));
function loadImage(file){return new Promise((resolve,reject)=>{const image=new Image(),url=URL.createObjectURL(file);image.onload=()=>{URL.revokeObjectURL(url);resolve(image);};image.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Image unavailable'));};image.src=url;});}
function cornerLight(data,width,height){const points=[[4,4],[width-5,4],[4,height-5],[width-5,height-5]],radius=Math.max(2,Math.round(Math.min(width,height)*.015));let total=0,count=0;for(const [cx,cy]of points)for(let y=Math.max(0,cy-radius);y<Math.min(height,cy+radius);y++)for(let x=Math.max(0,cx-radius);x<Math.min(width,cx+radius);x++){const i=(y*width+x)*4;total+=(data[i]+data[i+1]+data[i+2])/3;count++;}return total/Math.max(1,count);}
