function quality(read){const words=(read.data.words||[]).filter(word=>/[A-Za-z0-9]/.test(word.text||'')),confidence=words.length?words.reduce((sum,word)=>sum+(Number(word.confidence)||0),0)/words.length:Number(read.data.confidence)||0,junk=words.filter(word=>{const clean=(word.text||'').toLowerCase().replace(/[^a-z]/g,'');return clean.length>2&&!ocrWords.has(clean)&&(!/^[a-z]+$/.test(clean)||/(.)\1\1/.test(clean)||!/[aeiouy]/.test(clean)||(/^[A-Z]{2,4}$/.test(word.text||'')&&!['RAW','METHOD'].includes(word.text)));}).length;return {confidence,junkShare:words.length?junk/words.length:1};}
